book = {}
while True:
    parts = input().split()
    if parts[0] == "exit":
        break
    if parts[0] == "add":
        book[parts[1]] = parts[2]
    elif parts[0] == "find":
        print(book.get(parts[1], "غير موجود"))
    elif parts[0] == "list":
        for name in sorted(book):
            print(name + ": " + book[name])
    elif parts[0] == "delete":
        book.pop(parts[1], None)

